const now = new Date();
const y = now.getFullYear(), m = now.getMonth(), d = now.getDate();
const pad = n => String(n).padStart(2, '0');
const fmt = (Y, M, D) => `${Y}-${pad(M + 1)}-${pad(D)}`;
let start, end;
if (d >= 16) {            // run on the 16th -> cover 1st-15th of this month
  start = fmt(y, m, 1); end = fmt(y, m, 15);
} else {                  // run on the 1st -> cover 16th-end of previous month
  const last = new Date(y, m, 0);
  start = fmt(last.getFullYear(), last.getMonth(), 16);
  end = fmt(last.getFullYear(), last.getMonth(), last.getDate());
}
return [{ json: { period_start: start, period_end: end } }];

// Deterministic payroll math lives HERE (not in the AI).
const period = $('Compute Pay Period').first().json;
const punches = $('Get Timesheets').all().map(i => i.json);
const leaves = $('Get Approved Leave').all().map(i => i.json);
const holidays = new Set($('Get Holidays').all().map(i => i.json.date));

const STD_HOURS = 8;       // regular hours per day before overtime
const SHIFT_START = '09:00';
const LATE_GRACE_MIN = 10; // grace period before lateness counts
const MAX_HOURS = 16;      // above this = suspicious

const mins = (a, b) => Math.round((new Date(b) - new Date(a)) / 60000);
const byEmp = {};
const emp = (id, name) => (byEmp[id] ??= {
  employee_id: id, name, days_worked: 0, regular_hours: 0, overtime_hours: 0,
  holiday_hours: 0, late_minutes: 0, leave_days: 0, anomalies: []
});

for (const p of punches) {
  const e = emp(p.employee_id, p.name);
  if (!p.clock_in || !p.clock_out) { e.anomalies.push(`Missing punch on ${p.date}`); continue; }
  const worked = (mins(p.clock_in, p.clock_out) - (p.break_minutes ?? 60)) / 60;
  if (worked <= 0 || worked > MAX_HOURS) {
    e.anomalies.push(`Suspicious hours (${worked.toFixed(1)}h) on ${p.date}`); continue;
  }
  const ot = Math.max(worked - STD_HOURS, 0);
  if (holidays.has(p.date)) {
    e.holiday_hours += worked;
  } else {
    e.regular_hours += Math.min(worked, STD_HOURS);
    e.overtime_hours += ot;
  }
  if (ot > 0 && !p.ot_approved) e.anomalies.push(`Unapproved overtime ${ot.toFixed(1)}h on ${p.date}`);
  const late = Math.max(mins(`${p.date}T${SHIFT_START}:00`, p.clock_in) - LATE_GRACE_MIN, 0);
  e.late_minutes += late;
  e.days_worked += 1;
}

for (const l of leaves) {
  const e = emp(l.employee_id, l.name);
  e.leave_days += Number(l.days ?? 1);
}

const r2 = n => Math.round(n * 100) / 100;
const employees = Object.values(byEmp).map(e => ({
  ...e,
  regular_hours: r2(e.regular_hours), overtime_hours: r2(e.overtime_hours),
  holiday_hours: r2(e.holiday_hours)
}));
const anomalies = employees.flatMap(e => e.anomalies.map(issue => ({ employee_id: e.employee_id, name: e.name, issue })));

return [{ json: {
  period_start: period.period_start, period_end: period.period_end,
  headcount: employees.length,
  total_regular_hours: r2(employees.reduce((s, e) => s + e.regular_hours, 0)),
  total_overtime_hours: r2(employees.reduce((s, e) => s + e.overtime_hours, 0)),
  total_holiday_hours: r2(employees.reduce((s, e) => s + e.holiday_hours, 0)),
  anomaly_count: anomalies.length,
  anomalies, employees
} }];

